// The wire shapes of dataflow-rs-v4 0.0.0 as TypeScript: what a message, its
// context, a run, a trace and an issue serialize as. Generated by
// `v4/tests/ts_types.rs` from the crate's types; do not edit. To regenerate:
//
//     DATAFLOW_TS_WRITE=1 cargo test -p dataflow-rs-v4 --features ts --test ts_types

/**
 * Any JSON value: a payload, a context root, and the values a change holds.
 */
export type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue };

/**
 * A message as JSON: `{id, payload, context, audit_trail, errors}`, in that order.
 */
export type Message = {
  /**
   * The id: a UUID v7 unless set.
   */
  id: string,
  /**
   * The payload the message arrived with. It is not part of the evaluation
   * context.
   */
  payload: JsonValue,
  /**
   * The context.
   */
  context: Context,
  /**
   * The audit entries the run kept.
   */
  audit_trail: Array<AuditEntry>,
  /**
   * The errors recorded while processing.
   */
  errors: Array<ErrorRecord>,
};

/**
 * The context: `data`, `metadata` and `temp_data`, in that order. Each
 * root starts as an object; a trace's redacted root is `null`.
 */
export type Context = {
  /**
   * The `data` root.
   */
  data: JsonValue,
  /**
   * The `metadata` root.
   */
  metadata: JsonValue,
  /**
   * The `temp_data` root.
   */
  temp_data: JsonValue,
};

/**
 * One task's record, v3's `AuditTrail` on the wire.
 */
export type AuditEntry = {
  /**
   * The workflow the task belongs to.
   */
  workflow_id: string,
  /**
   * The task.
   */
  task_id: string,
  /**
   * When the entry was recorded.
   */
  timestamp: string,
  /**
   * The writes the task made, when changes are captured.
   */
  changes: Array<Change>,
  /**
   * The task's status code.
   */
  status: number,
  /**
   * The loop counter of the sweep that produced the entry.
   */
  loop_counter?: number,
  /**
   * The fan-out element the entry records.
   */
  element_index?: number,
};

/**
 * One write or removal, v3's `Change` on the wire.
 *
 * A path that was absent before the write records `old_value` as `null`.
 */
export type Change = {
  /**
   * The dotted path written.
   */
  path: string,
  /**
   * What the path held before; `null` when it was absent.
   */
  old_value: JsonValue,
  /**
   * The value written; `null` for a removal (read `Self::removed` to tell
   * a removal from a write of `null`).
   */
  new_value: JsonValue,
  /**
   * The key at `path` was removed rather than written. Skipped when
   * `false`, so a write's JSON is v3's.
   */
  removed?: boolean,
  /**
   * The write replaced the root at `path` instead of merging into it
   * (I106): a host's `Ctx::set` at a root replaces it, and `map`'s root
   * mapping, which records only the keys it wrote, merges. A trace's
   * changes carry it, so a replay knows which; an audit entry's always
   * read `false`, so the audit trail's JSON is v3's. Skipped when
   * `false`.
   */
  replaced?: boolean,
};

/**
 * v3's `ErrorInfo` on the wire: the same fields, in the same order, with the
 * same serde attributes.
 */
export type ErrorRecord = {
  /**
   * The error code.
   */
  code: string,
  /**
   * The human-readable message.
   */
  message: string,
  /**
   * Where the error happened, if known. Always serialized.
   */
  path: string | null,
  /**
   * The workflow it happened in.
   */
  workflow_id?: string,
  /**
   * The task it happened in.
   */
  task_id?: string,
  /**
   * When it happened.
   */
  timestamp?: string,
  /**
   * Whether a retry was attempted.
   */
  retry_attempted?: boolean,
  /**
   * How many retries were attempted.
   */
  retry_count?: number,
  /**
   * Operator-only detail; never to be shown to an untrusted caller.
   */
  detail?: string,
  /**
   * The fan-out element the error came from.
   */
  element_index?: number,
};

/**
 * A run's trace: `initial`, then each step's changes.
 *
 * Serialized as `{initial, steps, truncated}`, and read back from what it
 * writes: the text a trace read back writes is the text it was read from,
 * and its `contexts` are the original's.
 */
export type Trace = {
  /**
   * The context after the run's stamps and the error context's reset,
   * before any workflow, redacted.
   */
  initial: Context,
  /**
   * Every step, in the order the run made them.
   */
  steps: Array<TraceStep>,
  /**
   * The byte budget was crossed: from the step that crossed it on, every
   * step's changes are empty, so the contexts replayed from there on are
   * not whole.
   */
  truncated: boolean,
};

/**
 * One step of a `Trace`.
 *
 * Serialized with its keys in field order; `mapping_ends` and `errors` only
 * when not empty; `elapsed` as whole microseconds under `elapsed_us`, and
 * it, `loop_counter` and `element_index` only when present. Read back from
 * what it writes, so `elapsed` reads as the whole microseconds written, and
 * a missing `mapping_ends` or `errors` as empty.
 */
export type TraceStep = {
  /**
   * The workflow's position in the program.
   */
  workflow: WorkflowIx,
  /**
   * The workflow's id.
   */
  workflow_id: string,
  /**
   * The task's position in the program; `None` for the workflow's own
   * step: its skip, its failure, or the engine's writes as a sweep is
   * entered.
   */
  task: TaskIx | null,
  /**
   * The task's id; `None` with `task`.
   */
  task_id: string | null,
  /**
   * What the step was.
   */
  result: StepResult,
  /**
   * The call's status; `None` for a skip, a `Skip` outcome and the
   * engine's step.
   */
  status: number | null,
  /**
   * The step's changes in order: the engine's writes made for it first (a
   * fan-out's `into` pre-fill), then the call's own, then the progress
   * write, then the error context's. Empty past the byte budget and when
   * the trace records none.
   */
  changes: Array<Change>,
  /**
   * Where each of a `map`'s mappings ends in `changes` (I127): one entry
   * per mapping, in order, the index just past its last change, so
   * mapping `i`'s changes are `changes[ends[i - 1]..ends[i]]`, from 0 for
   * the first. A mapping that wrote nothing repeats the end before it.
   * Replaying `changes[..ends[i]]` gives the context after mapping `i`.
   * Empty for every other step, and whenever `changes` is.
   */
  mapping_ends?: Array<number>,
  /**
   * Every record the step added to the message, in the message's order
   * (I127): the call's own, then the recorder's (I96); for a workflow's
   * own failure, its record. A workflow whose condition failed to
   * evaluate (R34) adds none, and its `Skipped` step holds that failure's
   * record, which the message never gets.
   */
  errors?: Array<ErrorRecord>,
  /**
   * How long the call ran, when the trace asked for timings.
   */
  elapsed_us?: number,
  /**
   * The loop counter of the sweep: the call's, or the one the engine's
   * step wrote.
   */
  loop_counter?: number,
  /**
   * The fan-out element the call ran for.
   */
  element_index?: number,
};

/**
 * What a step was. Serialized, and read, as its lowercase name.
 */
export type StepResult = "executed" | "skipped" | "failed";

/**
 * The position of a workflow within a program. Serialized as its number,
 * and read from one.
 */
export type WorkflowIx = number;

/**
 * The position of a task within a program. Serialized as its number, and
 * read from one: any `u32`, so a position read for another program makes
 * `Program::task` panic.
 */
export type TaskIx = number;

/**
 * A run as JSON: how it ended and what each workflow did. Neither the trace
 * nor the arena counters are part of it.
 */
export type Run = {
  /**
   * How the run ended.
   */
  status: RunStatus,
  /**
   * The error that stopped the run: `stopped` only.
   */
  error?: DataflowError,
  /**
   * May running the message again succeed? True for a timeout and for a
   * stop whose error says so.
   */
  retryable: boolean,
  /**
   * Did the run end before every workflow was considered?
   */
  partial: boolean,
  /**
   * How many workflows were selected and ran.
   */
  matched: number,
  /**
   * Every workflow considered, in program order, up to and including the
   * one that stopped the run.
   */
  workflows: Array<WorkflowRecord>,
};

/**
 * How a run ended: a stopped run's error is its `error`.
 */
export type RunStatus = "completed" | "completed_with_errors" | "stopped" | "timed_out" | "cancelled";

/**
 * One workflow's part in a run.
 */
export type WorkflowRecord = {
  /**
   * The workflow's id.
   */
  id: string,
  /**
   * The workflow's position in the program.
   */
  index: WorkflowIx,
  /**
   * Whether it was selected.
   */
  selection: Selection,
  /**
   * Why its condition failed to evaluate: `condition_failed` only.
   */
  error?: DataflowError,
  /**
   * The sweeps begun: one for a workflow without a loop that ran, and for
   * a loop each sweep its condition admitted.
   */
  sweeps: number,
  /**
   * How it ended; `null` when it did not run.
   */
  exit: WorkflowExit | null,
};

/**
 * Why a workflow did or did not run: a failed condition's error is its
 * record's `error`.
 */
export type Selection = "ran" | "skipped_by_condition" | "condition_failed" | "skipped_by_rollout";

/**
 * How a workflow that ran ended.
 */
export type WorkflowExit = "completed" | "halted" | "failed" | "stopped";

/**
 * An error as JSON: `dataflow_rs::Error`'s code, message and whether a
 * retry may succeed.
 */
export type DataflowError = {
  /**
   * The recorded code.
   */
  code: string,
  /**
   * The human-readable message.
   */
  message: string,
  /**
   * May a retry succeed?
   */
  retryable: boolean,
};

/**
 * One finding about an authored definition.
 *
 * It serializes as an object of its seven fields, under their own names: the
 * code and severity as their strings, the path as it displays, the step kind
 * as `task`, `group` or `setup`, and an absent part as `null`.
 */
export type Issue = {
  /**
   * What it is about.
   */
  code: IssueCode,
  /**
   * When it bites. `IssueCode::severity` unless overridden.
   */
  severity: Severity,
  /**
   * Where in the authored JSON.
   */
  path: AuthoredPath,
  /**
   * The kind of step it sits in, if any.
   */
  step_kind: StepKind | null,
  /**
   * The id of the step it sits in, if known.
   */
  step_id: string | null,
  /**
   * The config field (the first key under `function.input`), if inside one.
   */
  field: string | null,
  /**
   * A human-readable explanation.
   */
  message: string,
};

/**
 * What an issue is about: its SCREAMING_SNAKE code, such as `UNKNOWN_FUNCTION`.
 */
export type IssueCode = string;

/**
 * When an issue bites.
 */
export type Severity = "REJECTED" | "DEFECT" | "ADVISORY";

/**
 * What kind of step an issue sits in.
 */
export type StepKind = "task" | "group" | "setup";

/**
 * A path in the authored JSON, as v3 spelled it: `tasks[1].tasks[0].id`.
 * The document itself is the empty string.
 */
export type AuthoredPath = string;
